private ClientConnection createClientConnection(HttpServerRequest request){
  try {
    return new ClientConnection(){
      @Override public String getRemoteAddr(){
        return request.remoteAddress().host();
      }
      @Override public String getRemoteHost(){
        return request.remoteAddress().host();
      }
      @Override public int getRemotePort(){
        return request.remoteAddress().port();
      }
      @Override public String getLocalAddr(){
        return request.localAddress().host();
      }
      @Override public int getLocalPort(){
        return request.localAddress().port();
      }
    };
  } catch (NullPointerException e) {
    throw new RuntimeException("Failed to create ClientConnection due to null address information", e);
  }
}
